```
private void checkEncoding(XmlContext context) {
    File file = context.getFile();
    byte[] bytes;
    try {
        bytes = Files.readAllBytes(file.toPath());
    } catch (IOException e) {
        return;
    }
    if (bytes.length == 0) return;
    String encoding = null;
    int offset = 0;
    if (bytes.length >= 4 && bytes[0] == 0x00 && bytes[1] == 0x00 && bytes[2] == (byte)0xFE && bytes[3] == (byte)0xFF) {
        encoding = "UTF-32BE";
    } else if (bytes.length >= 4 && bytes[0] == (byte)0xFF && bytes[1] == (byte)0xFE && bytes[2] == 0x00 && bytes[3] == 0x00) {
        encoding = "UTF-32LE";
    } else if (bytes.length >= 2 && bytes[0] == (byte)0xFE && bytes[1] == (byte)0xFF) {
        encoding = "UTF-16BE";
    } else if (bytes.length >= 2 && bytes[0] == (byte)0xFF && bytes[1] == (byte)0xFE) {
        encoding = "UTF-16LE";
    } else if (bytes.length >= 3 && bytes[0] == (byte)0xEF && bytes[1] == (byte)0xBB && bytes[2] == (byte)0xBF) {
        // UTF-8 BOM; still UTF-8. offset = 3.
        offset = 3;
    }
    if (encoding != null && !encoding.equalsIgnoreCase("UTF-8")) {
        report(context, encoding);
        return;
    }
    if (offset < bytes.length - 3) {
        // Check UTF-32/16 without BOM
        if (bytes[offset] == 0x00 && bytes[offset+1] == 0x00 && bytes[offset+2] == 0x00 && bytes[offset+3] == '<') {
            encoding = "UTF-32BE";
        } else if (bytes[offset] == '<' && bytes[offset+1] == 0x00 && bytes[offset+2] == 0x00 && bytes[offset+3] == 0x00) {
            encoding = "UTF-32LE";
        } else if (bytes[offset] == 0x00 && bytes[offset+1] == '<' && bytes[offset+2] == 0x00 && bytes[offset+3] == '?') {
            encoding = "UTF-16BE";
        } else if (bytes[offset] == '<' && bytes[offset+1] == 0x00 && bytes[offset+2] == '?' && bytes[offset+3] == 0x00) {
            encoding = "UTF-16LE";
        }
        if (encoding != null && !encoding.equalsIgnoreCase("UTF-8")) {
            report(context, encoding);
            return;
        }
    }
    // Single byte: parse declaration
    String text = new String(bytes, offset, bytes.length - offset, StandardCharsets.ISO_8859_1);
    if (text.startsWith("<?xml")) {
        int end = text.indexOf("?>");
        if (end != -1) {
            String decl = text.substring(0, end);
            String enc = extractEncoding(decl);
            if (enc != null && !enc.equalsIgnoreCase("UTF-8")) {
                report(context, enc);
                return;
            }
        }
    }
}
```
