```
private static String extractEncoding(String declaration) {
    int index = declaration.indexOf("encoding");
    if (index == -1) return null;
    index += 8;
    // skip whitespace and =
    while (index < declaration.length() && Character.isWhitespace(declaration.charAt(index))) index++;
    if (index >= declaration.length() || declaration.charAt(index) != '=') return null;
    index++;
    while (index < declaration.length() && Character.isWhitespace(declaration.charAt(index))) index++;
    if (index >= declaration.length()) return null;
    char quote = declaration.charAt(index);
    if (quote != '"' && quote != '\'') return null;
    int start = ++index;
    int end = declaration.indexOf(quote, start);
    if (end == -1) return null;
    return declaration.substring(start, end);
}
```

