private void checkEncoding(XmlContext context, Document document) {
    File file = context.getFile();
    if (!file.exists()) return;
    byte[] bytes;
    try {
        bytes = Files.readAllBytes(file.toPath());
    } catch (IOException e) {
        return;
    }
    if (bytes.length == 0) {
        return;
    }

    String encoding = null;
    int offset = 0;

    // BOM detection
    if (bytes.length >= 4 && bytes[0] == 0 && bytes[1] == 0 && bytes[2] == (byte)0xFE && bytes[3] == (byte)0xFF) {
        encoding = "UTF-32BE";
    } else if (bytes.length >= 4 && bytes[0] == (byte)0xFF && bytes[1] == (byte)0xFE && bytes[2] == 0 && bytes[3] == 0) {
        encoding = "UTF-32LE";
    } else if (bytes.length >= 2 && bytes[0] == (byte)0xFE && bytes[1] == (byte)0xFF) {
        encoding = "UTF-16BE";
    } else if (bytes.length >= 2 && bytes[0] == (byte)0xFF && bytes[1] == (byte)0xFE) {
        encoding = "UTF-16LE";
    } else if (bytes.length >= 3 && bytes[0] == (byte)0xEF && bytes[1] == (byte)0xBB && bytes[2] == (byte)0xBF) {
        offset = 3;
    }

    if (encoding != null) {
        report(context, encoding);
        return;
    }

    // No BOM: detect UTF-16/32 by null byte patterns
    if (offset + 7 < bytes.length) {
        if (bytes[offset] == 0 && bytes[offset + 1] == 0 && bytes[offset + 2] == 0 && bytes[offset + 3] == '<') {
            encoding = "UTF-32BE";
        } else if (bytes[offset] == '<' && bytes[offset + 1] == 0 && bytes[offset + 2] == 0 && bytes[offset + 3] == 0) {
            encoding = "UTF-32LE";
        } else if (bytes[offset] == 0 && bytes[offset + 1] == '<' && bytes[offset + 2] == 0 && bytes[offset + 3] == '?') {
            encoding = "UTF-16BE";
        } else if (bytes[offset] == '<' && bytes[offset + 1] == 0 && bytes[offset + 2] == '?' && bytes[offset + 3] == 0) {
            encoding = "UTF-16LE";
        }
    }
    if (encoding != null) {
        report(context, encoding);
        return;
    }

    // Treat as single-byte encoding and parse XML declaration
    String text = new String(bytes, offset, bytes.length - offset, StandardCharsets.ISO_8859_1);
    if (text.startsWith("<?xml")) {
        int end = text.indexOf("?>");
        if (end != -1) {
            String encodingValue = extractEncoding(text.substring(0, end + 2));
            if (encodingValue != null && !encodingValue.equalsIgnoreCase("UTF-8")) {
                report(context, encodingValue);
            }
        }
    }
}
```

